from sortedcontainers import SortedList

def main(n: int, k: int, p: list[int]) -> None:
    s = SortedList()
    idx = [0] * (n + 1)
    for i in range(n):
        idx[p[i]] = i
    ans = float('inf')
    for i in range(1, n + 1):
        s.add(idx[i])
        if len(s) > k:
            s.remove(idx[i - k])
        if len(s) == k:
            ans = min(ans, s[-1] - s[0])
    print(ans)
